@push('scripts')
<script>
document.querySelectorAll('[data-price-item-select]').forEach((select) => {
    const form = select.closest('[data-price-adjustment-form]');
    const price = form?.querySelector('[data-adjusted-price]');
    select.addEventListener('change', () => {
        if (price) price.value = select.selectedOptions[0]?.dataset.price ?? '';
    });
});
</script>
@endpush
@if($serviceRequest->price_minor>0)
@push('scripts')
<script>
document.querySelectorAll('[data-refund-form]').forEach((form) => {
    const type = form.querySelector('[data-refund-type]');
    const amount = form.querySelector('[data-refund-amount]');
    const syncRefundAmount = () => {
        const isFull = type.value === 'full';
        const isNone = type.value === 'none';
        if (isFull) amount.value = form.dataset.serviceAmount;
        if (isNone) amount.value = '';
        amount.readOnly = isFull;
        amount.disabled = isNone;
    };
    type.addEventListener('change', syncRefundAmount);
    syncRefundAmount();
});
</script>
@endpush
